Here is a simple implementation of a TCPClient in C# with as little code as possible:

```csharp
using System;
using System.Net;
using System.Net.Sockets;

class Program
{
    static void Main()
    {
        // Set IP address and port of the server you want to connect to
        string ipAddress = "127.0.0.1";
        int port = 8080;

        // Create a TCPClient and connect to the server
        using (TcpClient client = new TcpClient(ipAddress, port))
        {
            Console.WriteLine("Connected to server.");

            // Get the network stream from the client
            NetworkStream stream = client.GetStream();

            // Send data to the server
            byte[] data = System.Text.Encoding.ASCII.GetBytes("Hello, server!");
            stream.Write(data, 0, data.Length);

            // Receive data from the server
            data = new byte[1024];
            int bytesRead = stream.Read(data, 0, data.Length);
            string responseData = System.Text.Encoding.ASCII.GetString(data, 0, bytesRead);

            Console.WriteLine("Received from server: " + responseData);
        }
    }
}
```

This implementation establishes a connection to a server with the specified IP address and port, sends a message to the server, and receives a response. The code uses `TcpClient` to create a client and `NetworkStream` to send and receive data over the network.

