### TCPClient Implementation

1. **Create a New C# Script:**
   - Name it `SimpleTCPClient.cs`.

2. **Implement the Basic Functionality:**

```csharp
using UnityEngine;
using System.Net.Sockets;
using System.Text;

public class SimpleTCPClient : MonoBehaviour
{
    private TcpClient client;
    private NetworkStream stream;

    void Start()
    {
        ConnectToServer("127.0.0.1", 5000); // Change IP and port as needed
    }

    void ConnectToServer(string ip, int port)
    {
        client = new TcpClient(ip, port);
        stream = client.GetStream();
        SendMessage("Hello, Server!");
        ReceiveMessage();
    }

    void SendMessage(string message)
    {
        byte[] data = Encoding.ASCII.GetBytes(message);
        stream.Write(data, 0, data.Length);
    }

    void ReceiveMessage()
    {
        byte[] buffer = new byte[256];
        int bytes = stream.Read(buffer, 0, buffer.Length);
        string response = Encoding.ASCII.GetString(buffer, 0, bytes);
        Debug.Log("Received: " + response);
    }

    void OnApplicationQuit()
    {
        stream.Close();
        client.Close();
    }
}
```

