The Stoer-Wagner algorithm is used for finding the minimum cut in a weighted undirected graph. Here is a sample implementation of the Stoer-Wagner algorithm in Swift:

```swift
import Foundation

// Structure to represent a graph
struct Graph {
    var vertices: [String]
    var edges: [[Int]]

    init(vertices: [String]) {
        self.vertices = vertices
        self.edges = Array(repeating: Array(repeating: 0, count: vertices.count), count: vertices.count)
    }

    // Function to add an edge to the graph
    mutating func addEdge(from: Int, to: Int, weight: Int) {
        edges[from][to] = weight
        edges[to][from] = weight
    }

    // Stoer-Wagner algorithm implementation
    func stoerWagner() -> (cutValue: Int, partition: (Set<String>, Set<String>)) {
        var minCutValue = Int.max
        var bestParetn = (Set<String>(), Set<String>())
        var vertices = Array(0..<self.vertices.count)

        while vertices.count > 1 {
            let (lastAdded, lastWeight) = aMaxWeight(vertices: vertices)
            var inCut = Set<String>([self.vertices[lastAdded]])
            var weights = Array(repeating: 0, count: self.vertices.count)

            for _ in 0..<vertices.count-1 {
                var nextMax = -1
                var nextIndex = -1

                for v in vertices {
                    if inCut.contains(self.vertices[v]) {
                        continue
                    }
                    weights[v] += self.edges[lastAdded][v]

                    if weights[v] > nextMax {
                        nextMax = weights[v]
                        nextIndex = v
                    }
                }

                if nextIndex == -1 { break }
                inCut.insert(self.vertices[nextIndex])
                weights[nextIndex] = Int.min
            }

            let minCutValueCandidate = lastWeight
            if minCutValueCandidate < minCutValue {
                minCutValue = minCutValueCandidate
                let setA = inCut
                let setB = Set(self.vertices).subtracting(inCut)
                bestParetn = (setA, setB)
            }

            // Merge last added vertex into the last vertex
            if let last = vertices.firstIndex(of: lastAdded) {
                vertices.remove(at: last)
            }
            if let penultimate = vertices.firstIndex(of: vertices[vertices.count - 1]) {
                vertices[penultimate] = lastAdded
            }
        }

        return (minCutValue, bestParetn)
    }

    // Helper function that finds the last added vertex and its weight
    private func aMaxWeight(vertices: [Int]) -> (lastAdded: Int, lastWeight: Int) {
        var maxIndex = 0
        var maxWeight = -1

        for vertex in vertices {
            let weight = edges[vertex].reduce(0, +)
            if weight > maxWeight {
                maxWeight = weight
                maxIndex = vertex
            }
        }

        return (lastAdded: maxIndex, lastWeight: maxWeight)
    }
}

// Example usage
var graph = Graph(vertices: ["A", "B", "C", "D"])
graph.addEdge(from: 0, to: 1, weight: 3)
graph.addEdge(from: 0, to: 2, weight: 5)
graph.addEdge(from: 1, to: 2, weight: 1)
graph.addEdge(from: 1, to: 3, weight: 4)
graph.addEdge(from: 2, to: 3, weight: 2)

let (cutValue, partition) = graph.stoerWagner()
print("Minimum Cut Value: \(cutValue)")
print("Partition: \(partition)")
```

### Explanation:
1. **Graph Struct**: This contains the vertices and edges of the graph.
2. **Add Edge**: A method to add edges with weights between vertices.
3. **Stoer-Wagner Method**: Implements the algorithm to find the minimum cut.
4. **Max Weight Helper**: A function that identifies the vertex with the maximum weight in the current phase.
5. **Example Usage**: Creates a sample graph, adds edges, and computes the minimum cut, displaying the cut value and the vertex sets.

### Considerations:
- Ensure to handle edge cases such as disconnected graphs or graphs with no edges.
- This implementation assumes undirected graphs and non-negative weights.

